import re
"""
CAM Lease Analyzer Web App — Summary Document Generator

Generates per-tenant and batch summary DOCX documents from pipeline results.
Uses python-docx (already a dependency from the pipeline annotators).
"""

import json
import logging
from datetime import datetime
from pathlib import Path
from typing import List, Optional

from docx import Document
from docx.shared import Inches, Pt, RGBColor
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.enum.table import WD_TABLE_ALIGNMENT

logger = logging.getLogger(__name__)

DISCLAIMER = (
    "Generated by CAM\u2122 \u00b7 Patent Pending \u00b7 "
    "This report is a diagnostic tool and does not constitute legal advice."
)

SEVERITY_ORDER = ["CRITICAL", "HIGH", "MEDIUM", "LOW"]


def _get_resolution_notes(resolutions: Optional[dict], tenant_idx: Optional[int], provision_id: str) -> List[str]:
    if not resolutions or tenant_idx is None or not provision_id:
        return []
    entry = resolutions.get(f"{tenant_idx}:{provision_id}", {}) or {}
    notes = entry.get("notes", []) or []
    note_texts = []
    for note in notes:
        if isinstance(note, dict):
            text = str(note.get("text", "")).strip()
        else:
            text = str(note).strip()
        if text:
            note_texts.append(text)
    return note_texts


def _add_footer(doc: Document) -> None:
    """Add the standard disclaimer footer to all sections."""
    for section in doc.sections:
        footer = section.footer
        footer.is_linked_to_previous = False
        p = footer.paragraphs[0] if footer.paragraphs else footer.add_paragraph()
        p.text = DISCLAIMER
        p.alignment = WD_ALIGN_PARAGRAPH.CENTER
        run = p.runs[0] if p.runs else p.add_run(DISCLAIMER)
        run.font.size = Pt(8)
        run.font.color.rgb = RGBColor(0x99, 0x99, 0x99)


def _severity_label(sev: str) -> str:
    """Format severity for display."""
    mapping = {
        "CRITICAL": "\U0001f534 CRITICAL",
        "HIGH": "\u26a0\ufe0f HIGH",
        "MEDIUM": "\u26a0 MEDIUM",
        "LOW": "LOW",
        "CONFORMS": "\u2705 CONFORMS",
    }
    return mapping.get(sev, sev)


def _add_heading_styled(doc: Document, text: str, level: int = 1) -> None:
    """Add a heading with standard styling."""
    doc.add_heading(text, level=level)


def generate_tenant_summary(
    pipeline_results: dict,
    output_path: str,
    resolutions: Optional[dict] = None,
    tenant_idx: Optional[int] = None,
) -> str:
    """Generate a per-tenant summary DOCX document.

    Args:
        pipeline_results: Full pipeline results dict for one tenant.
        output_path: Path to write the DOCX file.

    Returns:
        Path to the generated file.
    """
    doc = Document()

    # Title
    title = doc.add_heading("Contract Analysis Summary", level=0)
    title.alignment = WD_ALIGN_PARAGRAPH.CENTER

    # Subtitle with tenant info
    tenant_file = pipeline_results.get("tenant_file", "Unknown")
    template_file = pipeline_results.get("template_file", "Unknown")
    timestamp = pipeline_results.get("timestamp", "")
    try:
        dt = datetime.fromisoformat(timestamp.replace("Z", "+00:00"))
        date_str = dt.strftime("%B %d, %Y")
    except (ValueError, AttributeError):
        date_str = timestamp[:10] if timestamp else "Unknown"

    sub = doc.add_paragraph()
    sub.alignment = WD_ALIGN_PARAGRAPH.CENTER
    run = sub.add_run(f"Tenant: {tenant_file}\nAnalysis Date: {date_str}")
    run.font.size = Pt(11)
    run.font.color.rgb = RGBColor(0x66, 0x66, 0x66)

    # ── Contract Overview ──
    metadata = pipeline_results.get("contract_metadata", {})
    _add_heading_styled(doc, "Contract Overview", level=1)

    meta_fields = [
        ("Landlord", metadata.get("landlord", "")),
        ("Tenant", metadata.get("tenant", "")),
        ("Property", metadata.get("property_description", "")),
        ("Effective Date", metadata.get("effective_date", "")),
        ("Term", metadata.get("term_length", "")),
        ("Expiration", metadata.get("expiration_date", "")),
        ("Governing Law", metadata.get("governing_law", "")),
        ("Base Rent", metadata.get("base_rent", "")),
        ("Permitted Use", metadata.get("permitted_use", "")),
    ]

    table = doc.add_table(rows=0, cols=2)
    table.style = "Light List Accent 1"
    for label, value in meta_fields:
        if value:
            row = table.add_row()
            row.cells[0].text = label
            row.cells[1].text = value

    if not any(v for _, v in meta_fields):
        doc.add_paragraph(
            "Contract metadata not available. "
            "Run analysis with updated extraction to populate this section."
        )

    # ── Summary Statistics ──
    summary = pipeline_results.get("summary", {})
    _add_heading_styled(doc, "Analysis Summary", level=1)

    stats_text = (
        f"Provisions analyzed: {summary.get('total_provisions_checked', 0)}\n"
        f"Conforming: {summary.get('conforms', 0)}\n"
        f"Deviations found: {summary.get('deviates', 0)}\n"
        f"Unclear: {summary.get('unclear', 0)}"
    )
    doc.add_paragraph(stats_text)

    sev_text = (
        f"Critical: {summary.get('critical', 0)}  |  "
        f"High: {summary.get('high', 0)}  |  "
        f"Medium: {summary.get('medium', 0)}  |  "
        f"Low: {summary.get('low', 0)}"
    )
    doc.add_paragraph(sev_text)

    # ── Deviations ──
    provisions = pipeline_results.get("provisions", [])
    deviations = [p for p in provisions if p.get("final_verdict") == "DEVIATES"]
    deviations.sort(
        key=lambda p: SEVERITY_ORDER.index(p.get("severity", "LOW"))
        if p.get("severity") in SEVERITY_ORDER else 99
    )

    if deviations:
        _add_heading_styled(doc, "Deviations (Review Recommended)", level=1)

        for d in deviations:
            pid = d.get("provision_id", "")
            pname = d.get("provision_name", "")
            sev = d.get("severity", "")
            section_ref = d.get("tenant_section_ref", "")

            heading_text = f"{pid} {pname} \u2014 {sev}"
            if section_ref:
                heading_text += f" \u2014 {section_ref}"
            doc.add_heading(heading_text, level=2)

            # What changed
            challenge = d.get("challenge_details", "")
            sev_reasoning = d.get("severity_reasoning", "")
            if challenge:
                doc.add_paragraph("What Changed:", style="List Bullet")
                doc.add_paragraph(challenge)
            if sev_reasoning:
                doc.add_paragraph("Impact:", style="List Bullet")
                doc.add_paragraph(sev_reasoning)

            # Evaluator info
            pattern = d.get("agreement_pattern", "")
            if pattern:
                doc.add_paragraph(f"Evaluator Agreement: {pattern}")

            # Fragility
            frag = d.get("fragility", {})
            if frag.get("fragile"):
                signals = ", ".join(frag.get("signals", []))
                doc.add_paragraph(f"Fragility Signals: {signals}")

            # Recommended action
            action = d.get("recommended_action", "")
            if action:
                doc.add_paragraph(f"Recommended Action: {action}")
            note_texts = _get_resolution_notes(resolutions, tenant_idx, pid)
            if note_texts:
                doc.add_paragraph("Attorney Notes:")
                for note_text in note_texts:
                    doc.add_paragraph(note_text, style="List Bullet")

            doc.add_paragraph("")  # spacer

    # ── Conforming Provisions ──
    conforming = [p for p in provisions if p.get("final_verdict") == "CONFORMS"]
    if conforming:
        _add_heading_styled(doc, "Conforming Provisions", level=1)
        for c in conforming:
            pid = c.get("provision_id", "")
            pname = c.get("provision_name", "")
            pattern = c.get("agreement_pattern", "")
            doc.add_paragraph(
                f"{pid} {pname} \u2014 {pattern}, conforms",
                style="List Bullet",
            )

    # ── Footer ──
    _add_footer(doc)

    # Save
    doc.save(output_path)
    logger.info(f"Tenant summary saved: {output_path}")
    return output_path


def generate_batch_summary(
    job: dict,
    tenant_results: List[dict],
    output_path: str,
) -> str:
    """Generate a batch summary DOCX covering all tenants.

    Args:
        job: The job dict with metadata.
        tenant_results: List of pipeline results dicts, one per tenant.
        output_path: Path to write the DOCX file.

    Returns:
        Path to the generated file.
    """
    doc = Document()

    # Title
    title = doc.add_heading("Batch Lease Analysis Summary", level=0)
    title.alignment = WD_ALIGN_PARAGRAPH.CENTER

    # ── Executive Summary ──
    _add_heading_styled(doc, "Executive Summary", level=1)

    template_name = ""
    if tenant_results:
        template_name = tenant_results[0].get("template_file", "Unknown")

    created_at = job.get("created_at", "")
    try:
        dt = datetime.fromisoformat(created_at.replace("Z", "+00:00"))
        date_str = dt.strftime("%B %d, %Y at %I:%M %p UTC")
    except (ValueError, AttributeError):
        date_str = created_at

    total_deviations = 0
    highest_severity = "CONFORMS"
    tenants_needing_review = 0
    total_api_calls = 0
    total_elapsed = 0.0

    for tr in tenant_results:
        s = tr.get("summary", {})
        devs = s.get("deviates", 0)
        total_deviations += devs
        if devs > 0:
            tenants_needing_review += 1
        total_api_calls += tr.get("api_calls_total", 0)
        total_elapsed += tr.get("elapsed_sec", 0)

        # Track highest severity
        for sev in SEVERITY_ORDER:
            if s.get(sev.lower(), 0) > 0:
                sev_idx = SEVERITY_ORDER.index(sev)
                curr_idx = SEVERITY_ORDER.index(highest_severity) if highest_severity in SEVERITY_ORDER else 99
                if sev_idx < curr_idx:
                    highest_severity = sev
                break

    exec_text = (
        f"Template: {template_name}\n"
        f"Tenants analyzed: {len(tenant_results)}\n"
        f"Analysis date: {date_str}\n"
        f"Total deviations found: {total_deviations}\n"
        f"Highest severity: {highest_severity}\n"
        f"Tenants requiring review: {tenants_needing_review}\n"
        f"Total API calls: {total_api_calls}\n"
        f"Total processing time: {round(total_elapsed / 60, 1)} minutes"
    )
    doc.add_paragraph(exec_text)

    # ── Comparison Table ──
    if tenant_results:
        _add_heading_styled(doc, "Comparison Table", level=1)

        # Collect all provision IDs from first result (they should be the same)
        provision_ids = []
        provision_names = {}
        if tenant_results[0].get("provisions"):
            for p in tenant_results[0]["provisions"]:
                pid = p.get("provision_id", "")
                provision_ids.append(pid)
                provision_names[pid] = p.get("provision_name", pid)

        if provision_ids:
            # Build table: header row + one row per tenant
            num_cols = min(len(provision_ids) + 1, 10)  # limit columns for readability
            shown_pids = provision_ids[:num_cols - 1]

            table = doc.add_table(rows=1 + len(tenant_results), cols=len(shown_pids) + 1)
            table.style = "Table Grid"
            table.alignment = WD_TABLE_ALIGNMENT.CENTER

            # Header
            hdr = table.rows[0]
            hdr.cells[0].text = "Tenant"
            for ci, pid in enumerate(shown_pids):
                hdr.cells[ci + 1].text = pid

            # Data rows
            for ri, tr in enumerate(tenant_results):
                row = table.rows[ri + 1]
                row.cells[0].text = tr.get("tenant_file", f"Tenant {ri + 1}")[:20]

                prov_map = {p["provision_id"]: p for p in tr.get("provisions", [])}
                for ci, pid in enumerate(shown_pids):
                    p = prov_map.get(pid, {})
                    verdict = p.get("final_verdict", "\u2014")
                    sev = p.get("severity", "")
                    if verdict == "CONFORMS":
                        row.cells[ci + 1].text = "\u2705"
                    elif verdict == "DEVIATES":
                        row.cells[ci + 1].text = sev or "DEV"
                    else:
                        row.cells[ci + 1].text = "\u2014"

            # If more provisions than shown
            if len(provision_ids) > len(shown_pids):
                doc.add_paragraph(
                    f"(Showing {len(shown_pids)} of {len(provision_ids)} provisions)"
                )

    # ── Per-Tenant Highlights ──
    _add_heading_styled(doc, "Per-Tenant Highlights", level=1)

    # Sort by risk (most deviations first)
    sorted_results = sorted(
        tenant_results,
        key=lambda tr: tr.get("summary", {}).get("deviates", 0),
        reverse=True,
    )

    for tr in sorted_results:
        tenant_file = tr.get("tenant_file", "Unknown")
        s = tr.get("summary", {})
        devs = s.get("deviates", 0)
        conforms = s.get("conforms", 0)

        doc.add_heading(tenant_file, level=2)

        if devs == 0:
            doc.add_paragraph(
                f"All {conforms} provisions conform to the standard template. "
                "No deviations detected."
            )
        else:
            # List deviations
            deviations = [
                p for p in tr.get("provisions", [])
                if p.get("final_verdict") == "DEVIATES"
            ]
            deviations.sort(
                key=lambda p: SEVERITY_ORDER.index(p.get("severity", "LOW"))
                if p.get("severity") in SEVERITY_ORDER else 99
            )

            lines = []
            for d in deviations:
                pid = d.get("provision_id", "")
                pname = d.get("provision_name", "")
                sev = d.get("severity", "")
                lines.append(f"{pid} {pname} ({sev})")

            doc.add_paragraph(
                f"{devs} deviation(s) found, {conforms} conforming:"
            )
            for line in lines:
                doc.add_paragraph(line, style="List Bullet")

    # ── Footer ──
    _add_footer(doc)

    # Save
    doc.save(output_path)
    logger.info(f"Batch summary saved: {output_path}")
    return output_path


