# ── Smart quote sanitization ──

def _sanitize_for_pdf(text: str) -> str:
    """Replace smart quotes and other Unicode chars that Helvetica can't render."""
    if not text:
        return text
    replacements = {
        '\u2018': "'",   # left single quote
        '\u2019': "'",   # right single quote
        '\u201C': '"',   # left double quote
        '\u201D': '"',   # right double quote
        '\u2013': '-',   # en dash
        '\u2014': '--',  # em dash
        '\u2026': '...',  # ellipsis
        '\u00A0': ' ',   # non-breaking space
        '\u2010': '-',   # hyphen
        '\u2011': '-',   # non-breaking hyphen
        '\u2012': '-',   # figure dash
        '\u2015': '--',  # horizontal bar
        '\u2032': "'",   # prime
        '\u2033': '"',   # double prime
        '\u00B7': '-',   # middle dot
    }
    for unicode_char, replacement in replacements.items():
        text = text.replace(unicode_char, replacement)
    # Strip markdown bold/italic markers
    text = re.sub(r'\*\*(.+?)\*\*', r'\1', text)  # **bold** -> bold
    text = re.sub(r'\*(.+?)\*', r'\1', text)        # *italic* -> italic
    text = re.sub(r'__(.+?)__', r'\1', text)          # __bold__ -> bold
    text = re.sub(r'_(.+?)_', r'\1', text)            # _italic_ -> italic
    return text


def _esc_xml(text: str) -> str:
    """Escape text for ReportLab Paragraph XML and sanitize smart quotes."""
    text = _sanitize_for_pdf(text or "")
    return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")


