_SEV_COLORS = {
    "CRITICAL": "#dc2626",
    "HIGH": "#c2410c",
    "MEDIUM": "#d97706",
    "LOW": "#64748b",
}


def _get_highest_severity(summary: dict) -> str:
    """Return the highest severity found in a summary dict."""
    for sev in SEVERITY_ORDER:
        if summary.get(sev.lower(), 0) > 0:
            return sev
    return "CONFORMS"


def generate_combined_summary_pdf(
    job: dict,
    tenant_results: List[dict],
    output_path: str,
) -> str:
    """Generate a single combined synopsis PDF covering all tenants.

    Uses ReportLab flowables for automatic page breaks — no manual Y tracking.

    Args:
        job: The job dict with metadata.
        tenant_results: List of pipeline results dicts, one per tenant.
        output_path: Path to write the PDF file.

    Returns:
        Path to the generated file.
    """
    try:
        return _generate_combined_synopsis_inner(job, tenant_results, output_path)
    except Exception as e:
        logger.error(f"Synopsis PDF layout failed ({e}), generating fallback...")
        return _generate_fallback_synopsis_pdf(job, tenant_results, output_path)


def _generate_fallback_synopsis_pdf(
    job: dict,
    tenant_results: List[dict],
    output_path: str,
) -> str:
    """Minimal fallback PDF if the flowable layout fails."""
    styles = _build_styles()
    doc = SimpleDocTemplate(
        output_path, pagesize=letter,
        leftMargin=72, rightMargin=72, topMargin=72, bottomMargin=72,
    )
    elements = []
    elements.append(Paragraph("CAM ANALYSIS SYNOPSIS", styles["SynopsisTitle"]))
    elements.append(Paragraph("(Simplified layout)", styles["SynopsisSubtitle"]))
    elements.append(Spacer(1, 10))

    for tenant_idx, tr in enumerate(tenant_results):
        tenant_file = tr.get("tenant_file", "Unknown")
        s = tr.get("summary", {})
        devs = s.get("deviates", 0)
        conforms = s.get("conforms", 0)

        elements.append(HRFlowable(width="100%", thickness=0.5, color=HexColor("#e2e8f0")))
        elements.append(Paragraph(_esc_xml(tenant_file), styles["TenantHeading"]))
        elements.append(Paragraph(f"Deviations: {devs}, Conforming: {conforms}", styles["BodyText"]))

        provisions = tr.get("provisions", [])
        deviations = [p for p in provisions if p.get("final_verdict") == "DEVIATES"]
        deviations.sort(
            key=lambda p: SEVERITY_ORDER.index(p.get("severity", "LOW"))
            if p.get("severity") in SEVERITY_ORDER else 99
        )
        for d in deviations:
            pid = d.get("provision_id", "")
            pname = d.get("provision_name", "")
            sev = d.get("severity", "")
            summary_text = d.get("challenge_details") or d.get("severity_reasoning") or ""
            elements.append(Paragraph(
                f"{_esc_xml(pid)} {_esc_xml(pname)} ({_esc_xml(sev)}): {_esc_xml(summary_text)}",
                styles["ClauseText"],
            ))
            for note_text in _get_resolution_notes(job.get("resolutions", {}), tenant_idx, pid):
                elements.append(Paragraph(
                    f"<b>Attorney Note:</b> {_esc_xml(note_text)}",
                    styles["ClauseText"],
                ))

    elements.append(Spacer(1, 20))
    elements.append(Paragraph(_sanitize_for_pdf(DISCLAIMER), styles["Disclaimer"]))
    doc.build(elements)
    logger.info(f"Fallback synopsis PDF saved: {output_path}")
    return output_path


def _generate_combined_synopsis_inner(
    job: dict,
    tenant_results: List[dict],
    output_path: str,
) -> str:
    """Lawyer-facing synopsis PDF using ReportLab flowables.

    Layout (Step 039L restructure):
      Page 1:   Deal Overview (parties, property, rent, term, key terms)
                Analysis Results (deviation counts, severity breakdown)
      Page 2+:  Findings per tenant — plain language memo style
                (risk_headline lead, plain English explanation, recommended action)
      Last pg:  Technical Appendix (models, timing, pipeline version)
    """
    styles = _build_styles()

    doc = SimpleDocTemplate(
        output_path, pagesize=letter,
        leftMargin=72, rightMargin=72, topMargin=72, bottomMargin=72,
    )
    elements = []

    # ── Gather metadata from first tenant ──
    first_result = tenant_results[0] if tenant_results else {}
    deal = first_result.get("deal_overview", {})
    meta = first_result.get("contract_metadata", {})
    models_used = first_result.get("models_used", {})

    created_at = job.get("created_at", "")
    try:
        dt = datetime.fromisoformat(created_at.replace("Z", "+00:00"))
        date_str = dt.strftime("%B %d, %Y")
    except (ValueError, AttributeError):
        date_str = created_at[:10] if created_at else "Unknown"

    job_id = job.get("job_id", "")

    # ── Aggregate stats ──
    total_deviations = 0
    total_provisions = 0
    sev_counts = {"CRITICAL": 0, "HIGH": 0, "MEDIUM": 0, "LOW": 0}
    total_api_calls = 0
    total_elapsed = 0.0

    for tr in tenant_results:
        s = tr.get("summary", {})
        total_deviations += s.get("deviates", 0)
        total_provisions += s.get("total_provisions_checked", 0)
        total_api_calls += tr.get("api_calls_total", 0)
        total_elapsed += tr.get("elapsed_sec", 0)
        for sev in sev_counts:
            sev_counts[sev] += s.get(sev.lower(), 0)

    # ════════════════════════════════════════════════
    # PAGE 1: HEADER + DEAL OVERVIEW + ANALYSIS RESULTS
    # ════════════════════════════════════════════════

    elements.append(Paragraph("CAM ANALYSIS SYNOPSIS", styles["SynopsisTitle"]))
    subtitle_parts = [_esc_xml(date_str)]
    if job_id:
        subtitle_parts.append(_esc_xml(job_id))
    elements.append(Paragraph(" | ".join(subtitle_parts), styles["SynopsisSubtitle"]))
    elements.append(Spacer(1, 10))

    # ── Deal Overview section ──
    elements.append(HRFlowable(width="100%", thickness=1.5, color=HexColor("#1a365d"),
                                spaceBefore=2, spaceAfter=6))
    elements.append(Paragraph("REFERENCE DOCUMENT OVERVIEW", styles["SynopsisHeading"]))
    elements.append(Paragraph(
        "<i>Standard template -- deviations from these terms are flagged below</i>",
        styles["SmallMuted"],
    ))
    elements.append(HRFlowable(width="100%", thickness=1.5, color=HexColor("#1a365d"),
                                spaceBefore=2, spaceAfter=8))

    # Build deal overview rows from deal_overview (preferred) or fall back to contract_metadata
    landlord = deal.get("landlord_name") or meta.get("landlord", "")
    tenant_name = deal.get("tenant_name") or meta.get("tenant", "")
    property_addr = deal.get("property_address") or meta.get("property_description", "")
    property_type = deal.get("property_type", "")
    lease_term = deal.get("lease_term_years")
    commencement = deal.get("commencement_date") or meta.get("effective_date", "")
    expiration = deal.get("expiration_date") or meta.get("expiration_date", "")
    renewal = deal.get("renewal_options", "")
    base_rent = deal.get("base_rent_monthly") or meta.get("base_rent", "")
    escalation = deal.get("escalation", "")
    security = deal.get("security_deposit", "")
    cam_structure = deal.get("cam_structure", "")
    permitted_use = deal.get("permitted_use") or meta.get("permitted_use", "")
    key_terms = deal.get("key_terms_summary", [])

    # Format term string
    term_str = ""
    if lease_term:
        term_str = f"{lease_term} year{'s' if lease_term != 1 else ''}"
        if commencement and expiration:
            term_str += f" ({commencement} -- {expiration})"
        elif commencement:
            term_str += f" (from {commencement})"
    elif meta.get("term_length"):
        term_str = meta.get("term_length", "")
        if commencement:
            term_str += f" (from {commencement})"

    # Parties
    if landlord and tenant_name:
        parties_str = f"{landlord} (Landlord) / {tenant_name} (Tenant)"
    elif landlord:
        parties_str = f"Landlord: {landlord}"
    elif tenant_name:
        parties_str = f"Tenant: {tenant_name}"
    else:
        parties_str = ""

    # Render deal overview as label: value rows
    deal_rows = [
        ("Parties", parties_str),
        ("Property", property_addr),
        ("Lease Type", property_type),
        ("Term", term_str),
        ("Renewal", renewal),
        ("Rent", base_rent),
        ("Escalation", escalation),
        ("Security", security),
        ("CAM/OpEx", cam_structure),
        ("Permitted Use", permitted_use),
    ]

    has_any_deal_data = any(v for _, v in deal_rows)
    if has_any_deal_data:
        for label, value in deal_rows:
            if value:
                elements.append(Paragraph(
                    f'<b>{_esc_xml(label)}:</b>  {_esc_xml(str(value))}',
                    styles["DealRow"],
                ))

        # Key Terms bullets
        if key_terms:
            elements.append(Spacer(1, 4))
            elements.append(Paragraph("<b>Key Terms:</b>", styles["DealRow"]))
            for term in key_terms:
                if term:
                    elements.append(Paragraph(
                        f"&bull; {_esc_xml(term)}",
                        styles["KeyTermBullet"],
                    ))
    else:
        elements.append(Paragraph(
            "Deal overview not available. Run analysis with updated extraction to populate this section.",
            styles["BodyText"],
        ))

    elements.append(Spacer(1, 14))

    # ── Run Synopsis summary ──
    elements.append(HRFlowable(width="100%", thickness=0.5, color=HexColor("#e2e8f0"),
                                spaceBefore=4, spaceAfter=6))
    elements.append(Paragraph("RUN SYNOPSIS", styles["SynopsisHeading"]))

    elements.append(Paragraph(
        f"{total_deviations} deviation{'s' if total_deviations != 1 else ''} "
        f"found across {total_provisions} provisions analyzed",
        styles["BodyBold"],
    ))
    if len(tenant_results) > 1:
        elements.append(Paragraph(f"Tenants reviewed: {len(tenant_results)}", styles["BodyText"]))

    sev_parts = []
    for sev_label in SEVERITY_ORDER:
        count = sev_counts.get(sev_label, 0)
        if count > 0:
            sev_parts.append(f"{count} {sev_label}")
    if sev_parts:
        elements.append(Paragraph(" | ".join(sev_parts), styles["BodyText"]))

    elements.append(Spacer(1, 12))

    # ── Provision Checklist (traffic-light grid, matches screen) ──
    # For single tenant, show from the first result; for multi-tenant, aggregate
    all_provisions_for_checklist = []
    if len(tenant_results) == 1:
        all_provisions_for_checklist = tenant_results[0].get("provisions", [])
    else:
        # Aggregate: show each provision once with worst severity across tenants
        prov_worst = {}  # pid -> provision dict (with worst severity)
        for tr in tenant_results:
            for p in tr.get("provisions", []):
                pid = p.get("provision_id", "")
                if not pid:
                    continue
                if pid not in prov_worst:
                    prov_worst[pid] = dict(p)
                else:
                    existing = prov_worst[pid]
                    # Upgrade verdict
                    if p.get("final_verdict") == "DEVIATES" and existing.get("final_verdict") != "DEVIATES":
                        prov_worst[pid] = dict(p)
                    elif p.get("final_verdict") == "DEVIATES" and existing.get("final_verdict") == "DEVIATES":
                        # Keep higher severity
                        e_idx = SEVERITY_ORDER.index(existing.get("severity", "LOW")) if existing.get("severity") in SEVERITY_ORDER else 99
                        p_idx = SEVERITY_ORDER.index(p.get("severity", "LOW")) if p.get("severity") in SEVERITY_ORDER else 99
                        if p_idx < e_idx:
                            prov_worst[pid] = dict(p)
                    elif p.get("final_verdict") == "UNCLEAR" and existing.get("final_verdict") == "CONFORMS":
                        prov_worst[pid] = dict(p)
        all_provisions_for_checklist = list(prov_worst.values())

    if all_provisions_for_checklist:
        elements.append(HRFlowable(width="100%", thickness=0.5, color=HexColor("#e2e8f0"),
                                    spaceBefore=4, spaceAfter=6))
        elements.append(Paragraph("PROVISION CHECKLIST", styles["SynopsisHeading"]))

        # Group by severity bucket
        sev_groups = {"CRITICAL": [], "HIGH": [], "MEDIUM": [], "LOW": [], "CONFORMS": [], "UNCLEAR": []}
        for p in all_provisions_for_checklist:
            verdict = p.get("final_verdict", "")
            if verdict == "DEVIATES":
                sev = p.get("severity", "MEDIUM")
                if sev in sev_groups:
                    sev_groups[sev].append(p)
                else:
                    sev_groups["MEDIUM"].append(p)
            elif verdict == "UNCLEAR":
                sev_groups["UNCLEAR"].append(p)
            else:
                sev_groups["CONFORMS"].append(p)

        sev_icons = {"CRITICAL": "\u2715", "HIGH": "\u25cf", "MEDIUM": "\u25cb", "LOW": "\u2013", "CONFORMS": "\u2713", "UNCLEAR": "\u25ca"}
        sev_checklist_colors = {
            "CRITICAL": "#dc2626", "HIGH": "#c2410c", "MEDIUM": "#d97706",
            "LOW": "#64748b", "CONFORMS": "#16a34a", "UNCLEAR": "#7c3aed",
        }
        for sev_key in ["CRITICAL", "HIGH", "MEDIUM", "LOW", "UNCLEAR", "CONFORMS"]:
            items = sev_groups.get(sev_key, [])
            if not items:
                continue
            color = sev_checklist_colors.get(sev_key, "#64748b")
            icon = sev_icons.get(sev_key, "[-]")
            label = "Needs Review" if sev_key == "UNCLEAR" else sev_key.title()
            names = ", ".join(
                f"{_esc_xml(p.get('provision_id', ''))} {_esc_xml(p.get('provision_name', ''))}"
                for p in items
            )
            elements.append(Paragraph(
                f'<font color="{color}"><b>{icon} {label}:</b></font>  {names}',
                styles["BodyText"],
            ))

        elements.append(Spacer(1, 8))

    # ── Batch Summary Table (multi-tenant only, matches screen) ──
    if len(tenant_results) > 1:
        elements.append(HRFlowable(width="100%", thickness=0.5, color=HexColor("#e2e8f0"),
                                    spaceBefore=4, spaceAfter=6))
        elements.append(Paragraph("CONTRACT STATUS SNAPSHOT", styles["SynopsisHeading"]))

        # Sort by severity (most severe first)
        batch_sorted = sorted(
            tenant_results,
            key=lambda tr: (
                SEVERITY_ORDER.index(_get_highest_severity(tr.get("summary", {})))
                if _get_highest_severity(tr.get("summary", {})) in SEVERITY_ORDER else 99
            ),
        )

        for tr in batch_sorted:
            t_name = _format_tenant_name(tr.get("tenant_file", "Unknown"))
            s = tr.get("summary", {})
            devs = s.get("deviates", 0)
            highest = _get_highest_severity(s)

            if s.get("critical", 0) > 0:
                action = "Immediate"
            elif s.get("high", 0) > 0:
                action = "Review"
            elif devs > 0:
                action = "Monitor"
            else:
                action = "No action"

            sev_color = _SEV_COLORS.get(highest, "#16a34a")
            elements.append(Paragraph(
                f'{_esc_xml(t_name)}:  {devs} deviation{"s" if devs != 1 else ""}  |  '
                f'<font color="{sev_color}"><b>{_esc_xml(highest)}</b></font>  |  '
                f'{_esc_xml(action)}',
                styles["BodyText"],
            ))

        elements.append(Spacer(1, 8))

    # ── Cross-Contract Issue Matrix (multi-tenant only) ──
    if len(tenant_results) > 1:
        # Aggregate: for each provision_id, which tenants have it as DEVIATES?
        issue_map = {}  # pid -> { pname, severity, tenants: [filename] }
        clean_tenants = []
        for tr in tenant_results:
            tenant_file = _format_tenant_name(tr.get("tenant_file", "Unknown"))
            has_deviation = False
            for p in tr.get("provisions", []):
                if p.get("final_verdict") == "DEVIATES":
                    has_deviation = True
                    pid = p.get("provision_id", "")
                    if pid not in issue_map:
                        issue_map[pid] = {
                            "pname": p.get("provision_name", pid),
                            "severity": p.get("severity", "MEDIUM"),
                            "tenants": [],
                        }
                    # Track highest severity across tenants
                    existing_idx = SEVERITY_ORDER.index(issue_map[pid]["severity"]) if issue_map[pid]["severity"] in SEVERITY_ORDER else 99
                    this_idx = SEVERITY_ORDER.index(p.get("severity", "MEDIUM")) if p.get("severity", "MEDIUM") in SEVERITY_ORDER else 99
                    if this_idx < existing_idx:
                        issue_map[pid]["severity"] = p.get("severity", "MEDIUM")
                    issue_map[pid]["tenants"].append(tenant_file)
            if not has_deviation:
                clean_tenants.append(tenant_file)

        if issue_map or clean_tenants:
            elements.append(HRFlowable(width="100%", thickness=0.5, color=HexColor("#e2e8f0"),
                                        spaceBefore=4, spaceAfter=6))
            elements.append(Paragraph("CROSS-CONTRACT ISSUE MATRIX", styles["SynopsisHeading"]))

            issues = sorted(
                issue_map.items(),
                key=lambda x: SEVERITY_ORDER.index(x[1]["severity"]) if x[1]["severity"] in SEVERITY_ORDER else 99,
            )
            sev_markers = {"CRITICAL": "[!]", "HIGH": "[!]", "MEDIUM": "[*]", "LOW": "[-]"}
            for pid, info in issues:
                sev = info["severity"]
                sev_color = _SEV_COLORS.get(sev, "#64748b")
                marker = sev_markers.get(sev, "[-]")
                pname_short = (info["pname"] or "").split(" ", 1)[-1] if info["pname"] else ""
                tenant_list = ", ".join(info["tenants"])
                elements.append(Paragraph(
                    f'<font color="{sev_color}"><b>{marker} {_esc_xml(pid)} {_esc_xml(pname_short)}</b></font>'
                    f'  --  {_esc_xml(tenant_list)}',
                    styles["BodyText"],
                ))

            if clean_tenants:
                elements.append(Paragraph(
                    f'<font color="#16a34a"><b>[OK] All provisions conform</b></font>'
                    f'  --  {_esc_xml(", ".join(clean_tenants))}',
                    styles["BodyText"],
                ))

            elements.append(Spacer(1, 8))

    # ════════════════════════════════════════════════
    # PAGE 2+: Contract Findings (plain language, per contract)
    # ════════════════════════════════════════════════

    elements.append(HRFlowable(width="100%", thickness=0.5, color=HexColor("#e2e8f0"),
                                spaceBefore=4, spaceAfter=6))
    # ════════════════════════════════════════════════
    # COVERAGE & GAPS SECTION
    # ════════════════════════════════════════════════

    # Collect coverage issues across all tenants
    coverage_issues = []
    for tr in tenant_results:
        ca = tr.get("coverage_assessment", [])
        tenant_file = tr.get("tenant_file", "")
        for item in ca:
            state = item.get("coverage_state", "covered")
            if state in ("missing", "partial", "covered_unfavorable"):
                coverage_issues.append({
                    "pid": item.get("issue_area_id", ""),
                    "name": item.get("provision_name", item.get("issue_area_id", "")),
                    "state": state,
                    "materiality": item.get("materiality", "medium"),
                    "exposure": item.get("exposure_statement", ""),
                    "tenant": tenant_file,
                    "elements_missing": item.get("elements_missing", []),
                })

    if coverage_issues:
        # Sort: high materiality first
        mat_order = {"high": 0, "medium": 1, "low": 2}
        coverage_issues.sort(key=lambda x: mat_order.get(x["materiality"], 1))

        elements.append(HRFlowable(width="100%", thickness=0.5, color=HexColor("#e2e8f0"),
                                   spaceBefore=12, spaceAfter=8))
        elements.append(Paragraph("COVERAGE & GAPS", styles["SynopsisHeading"]))
        elements.append(Spacer(1, 4))
        elements.append(Paragraph(
            "The following provisions were present but incomplete, unfavorable, or missing entirely.",
            styles["FindingBody"],
        ))
        elements.append(Spacer(1, 6))

        state_labels = {
            "missing": "MISSING",
            "partial": "INCOMPLETE",
            "covered_unfavorable": "UNFAVORABLE TERMS",
        }
        state_colors = {
            "missing": "#c2410c",
            "partial": "#856404",
            "covered_unfavorable": "#0369a1",
        }
        mat_icons = {"high": "!", "medium": "~", "low": "-"}

        for issue in coverage_issues:
            state = issue["state"]
            label = state_labels.get(state, state.upper())
            color = state_colors.get(state, "#64748b")
            icon = mat_icons.get(issue["materiality"], "~")
            pid = issue["pid"]
            name = issue["name"] or pid
            exposure = _sanitize_for_pdf(issue["exposure"] or "")
            missing_els = issue.get("elements_missing", [])

            # Heading line
            heading_line = (
                f'[{icon}] <font color="{color}"><b>{_esc_xml(pid)} {_esc_xml(name)}</b></font>'
                f' <font color="#64748b">— {_esc_xml(label)}</font>'
            )
            elements.append(Paragraph(heading_line, styles["FindingBody"]))

            # Missing elements if any
            if missing_els:
                missing_str = ", ".join(_esc_xml(str(e)) for e in missing_els[:5])
                elements.append(Paragraph(
                    f'<i>Missing: {missing_str}</i>',
                    styles["ClauseText"],
                ))

            # Exposure statement
            if exposure:
                elements.append(Paragraph(_esc_xml(exposure), styles["ClauseText"]))

            elements.append(Spacer(1, 4))

        elements.append(Spacer(1, 6))

    # ════════════════════════════════════════════════
    # COVERAGE & GAPS SECTION
    # ════════════════════════════════════════════════
    coverage_issues = []
    for tr in tenant_results:
        ca = tr.get("coverage_assessment", [])
        for item in ca:
            state = item.get("coverage_state", "covered")
            if state in ("missing", "partial", "covered_unfavorable"):
                coverage_issues.append({
                    "pid": item.get("issue_area_id", ""),
                    "name": item.get("provision_name", item.get("issue_area_id", "")),
                    "state": state,
                    "materiality": item.get("materiality", "medium"),
                    "exposure": item.get("exposure_statement", ""),
                    "elements_missing": item.get("elements_missing", []),
                })

    if coverage_issues:
        mat_order = {"high": 0, "medium": 1, "low": 2}
        coverage_issues.sort(key=lambda x: mat_order.get(x["materiality"], 1))
        elements.append(HRFlowable(width="100%", thickness=0.5, color=HexColor("#e2e8f0"),
                                   spaceBefore=12, spaceAfter=8))
        elements.append(Paragraph("COVERAGE & GAPS", styles["SynopsisHeading"]))
        elements.append(Spacer(1, 4))
        elements.append(Paragraph(
            "The following provisions were present but incomplete, unfavorable, or missing entirely.",
            styles["FindingBody"],
        ))
        elements.append(Spacer(1, 6))
        state_labels = {"missing": "MISSING", "partial": "INCOMPLETE", "covered_unfavorable": "UNFAVORABLE TERMS"}
        state_colors = {"missing": "#c2410c", "partial": "#856404", "covered_unfavorable": "#0369a1"}
        mat_icons = {"high": "!", "medium": "~", "low": "-"}
        for issue in coverage_issues:
            state = issue["state"]
            label = state_labels.get(state, state.upper())
            color = state_colors.get(state, "#64748b")
            icon = mat_icons.get(issue["materiality"], "~")
            pid = issue["pid"]
            name = issue["name"] or pid
            exposure = _sanitize_for_pdf(issue["exposure"] or "")
            missing_els = issue.get("elements_missing", [])
            heading_line = (
                f'[{icon}] <font color="{color}"><b>{_esc_xml(pid)} {_esc_xml(name)}</b></font>'
                f' <font color="#64748b">-- {_esc_xml(label)}</font>'
            )
            elements.append(Paragraph(heading_line, styles["FindingBody"]))
            if missing_els:
                missing_str = ", ".join(_esc_xml(str(e)) for e in missing_els[:5])
                elements.append(Paragraph(f'<i>Missing elements: {missing_str}</i>', styles["ClauseText"]))
            if exposure:
                elements.append(Paragraph(_esc_xml(exposure), styles["ClauseText"]))
            elements.append(Spacer(1, 4))
        elements.append(Spacer(1, 6))

    elements.append(Paragraph("CONTRACT FINDINGS", styles["SynopsisHeading"]))

    sorted_results = sorted(
        tenant_results,
        key=lambda tr: tr.get("summary", {}).get("deviates", 0),
        reverse=True,
    )

    for tr in sorted_results:
        tenant_idx = tenant_results.index(tr)
        tenant_file = tr.get("tenant_file", "Unknown")
        tenant_display = _format_tenant_name(tenant_file)
        s = tr.get("summary", {})
        devs = s.get("deviates", 0)
        total = s.get("total_provisions_checked", 0)

        # Show tenant heading only for multi-tenant batches
        if len(tenant_results) > 1:
            elements.append(HRFlowable(width="100%", thickness=0.5, color=HexColor("#e2e8f0"),
                                        spaceBefore=10, spaceAfter=4))
            elements.append(Paragraph(f"TENANT: {_esc_xml(tenant_display)}", styles["TenantHeading"]))

            # Per-tenant contract metadata (matches screen's Contract Summary section)
            t_meta = tr.get("contract_metadata", {})
            t_deal = tr.get("deal_overview", {})
            t_landlord = t_deal.get("landlord_name") or t_meta.get("landlord", "")
            t_tenant_name = t_deal.get("tenant_name") or t_meta.get("tenant", "")
            t_property = t_deal.get("property_address") or t_meta.get("property_description", "")
            t_rent = t_deal.get("base_rent_monthly") or t_meta.get("base_rent", "")
            t_term = t_meta.get("term_length", "")
            t_permitted = t_deal.get("permitted_use") or t_meta.get("permitted_use", "")

            meta_rows = []
            if t_landlord:   meta_rows.append(f"Landlord: {t_landlord}")
            if t_tenant_name: meta_rows.append(f"Tenant: {t_tenant_name}")
            if t_property:   meta_rows.append(f"Property: {t_property}")
            if t_rent:       meta_rows.append(f"Base Rent: {t_rent}")
            if t_term:       meta_rows.append(f"Term: {t_term}")
            if t_permitted:  meta_rows.append(f"Permitted Use: {t_permitted}")

            if meta_rows:
                elements.append(Paragraph(
                    _esc_xml("  |  ".join(meta_rows)),
                    styles["SmallMuted"],
                ))

        # List deviations and unclear sorted by severity — memo style
        provisions = tr.get("provisions", [])
        findings = [p for p in provisions
                     if p.get("final_verdict") in ("DEVIATES", "UNCLEAR")]

        if not findings:
            elements.append(Paragraph(
                f"All {total} provisions conform to the standard template. No deviations detected.",
                styles["Conforming"],
            ))
            continue
        findings.sort(
            key=lambda p: SEVERITY_ORDER.index(p.get("severity", "LOW"))
            if p.get("severity") in SEVERITY_ORDER else 99
        )

        for d in findings:
            pid = d.get("provision_id", "")
            pname = d.get("provision_name", "")
            sev = d.get("severity", "")
            is_unclear = d.get("final_verdict") == "UNCLEAR"
            risk_headline = d.get("risk_headline", "")
            challenge_details = d.get("challenge_details", "")
            sev_reasoning = d.get("severity_reasoning", "")
            financial_impact = d.get("financial_impact", "")
            action = d.get("recommended_action", "")
            note_texts = _get_resolution_notes(job.get("resolutions", {}), tenant_idx, pid)
            section_ref = d.get("tenant_section_ref", "")
            agreement_pattern = d.get("agreement_pattern", "")
            template_text = d.get("template_text", "")
            tenant_text = d.get("tenant_text", "")

            # Display label: "Needs Review" for UNCLEAR, severity for DEVIATES
            display_sev = "Needs Review" if is_unclear else sev
            sev_color = "#7c3aed" if is_unclear else _SEV_COLORS.get(sev, "#64748b")

            # Memo-style finding: heading, then plain English body
            finding_els = []

            # Heading: "LP-07 CAM Charges -- HIGH" (with section ref if available)
            heading = f'{_esc_xml(pid)} {_esc_xml(pname)} -- '
            heading += f'<font color="{sev_color}"><b>{_esc_xml(display_sev)}</b></font>'
            if section_ref:
                heading += f'  <font color="#64748b">({_esc_xml(section_ref)})</font>'
            finding_els.append(Paragraph(heading, styles["FindingHeading"]))

            # Agreement pattern badge (e.g. "2-1 split")
            if agreement_pattern:
                is_unanimous = agreement_pattern.startswith("3-0") or agreement_pattern.startswith("2-0")
                if not is_unanimous:
                    finding_els.append(Paragraph(
                        f'<font color="#64748b">Evaluator agreement: {_esc_xml(agreement_pattern)}</font>',
                        styles["SmallMuted"],
                    ))

            # Body: risk_headline leads, then challenge_details or severity_reasoning
            body_parts = []
            if risk_headline:
                body_parts.append(risk_headline)
            if challenge_details:
                body_parts.append(challenge_details)
            elif sev_reasoning:
                body_parts.append(sev_reasoning)

            if body_parts:
                finding_els.append(Paragraph(
                    _esc_xml(" ".join(body_parts)),
                    styles["FindingBody"],
                ))

            # ── Evaluator votes block (matches screen's evaluator section) ──
            evaluator_verdicts = d.get("evaluator_verdicts", {})
            evaluator_reasoning = d.get("evaluator_reasoning", {})
            evaluator_confidences = d.get("evaluator_confidences", {})
            if evaluator_verdicts:
                finding_els.append(Paragraph("<b>Evaluator Votes:</b>", styles["FindingBody"]))
                for ev_key in ["A", "B", "C"]:
                    ev_verdict = evaluator_verdicts.get(ev_key, "")
                    if not ev_verdict or ev_verdict == "(evaluator unavailable)":
                        continue
                    ev_conf = evaluator_confidences.get(ev_key)
                    ev_reason = evaluator_reasoning.get(ev_key, "")
                    conf_str = f" ({ev_conf:.0%})" if ev_conf and ev_conf > 0 else ""
                    ev_color = "#c2410c" if ev_verdict == "DEVIATES" else "#16a34a" if ev_verdict == "CONFORMS" else "#64748b"
                    ev_line = (
                        f'  <b>{_esc_xml(ev_key)}:</b>  '
                        f'<font color="{ev_color}"><b>{_esc_xml(ev_verdict)}</b></font>'
                        f'{_esc_xml(conf_str)}'
                    )
                    finding_els.append(Paragraph(ev_line, styles["ClauseLabel"]))
                    if ev_reason and ev_reason.strip() != "(evaluator unavailable)":
                        # Truncate long reasoning to ~200 chars for PDF conciseness
                        short_reason = ev_reason.strip()
                        if len(short_reason) > 120:
                            short_reason = short_reason[:117] + "..."
                        finding_els.append(Paragraph(
                            f'<i>{_esc_xml(short_reason)}</i>',
                            styles["ClauseText"],
                        ))

            # Template vs Tenant language (matches screen's side-by-side view)
            if template_text or tenant_text:
                # Use AI interpretation note if available; otherwise show clean 2-sentence excerpt
                interpretation_note = d.get("interpretation_note", "")
                if interpretation_note and interpretation_note.strip():
                    # Strip markdown from interpretation note
                    clean_note = _sanitize_for_pdf(interpretation_note.strip())
                    finding_els.append(Paragraph(
                        f'<b>Interpretation:</b>  {_esc_xml(clean_note)}',
                        styles["ClauseText"],
                    ))
                else:
                    # Fall back to clean 2-sentence excerpt of tenant clause
                    if tenant_text:
                        sentences = [s.strip() for s in tenant_text.replace("\n", " ").split(".") if s.strip()]
                        excerpt = ". ".join(sentences[:2])
                        if excerpt and not excerpt.endswith("."):
                            excerpt += "."
                        if len(sentences) > 2:
                            excerpt += " [See annotated document for full clause text.]"
                        finding_els.append(Paragraph(
                            f'<b>Tenant Clause:</b>  {_esc_xml(excerpt)}',
                            styles["ClauseText"],
                        ))

            # Impact / severity reasoning (shown separately if challenge_details was present)
            if sev_reasoning and challenge_details:
                finding_els.append(Paragraph(
                    f'<b>Impact:</b>  {_esc_xml(sev_reasoning)}',
                    styles["FindingBody"],
                ))

            # Financial impact
            if financial_impact:
                finding_els.append(Paragraph(
                    f'<b>Financial Impact:</b>  {_esc_xml(financial_impact)}',
                    styles["FindingBody"],
                ))

            # Recommended action in italic
            if action:
                finding_els.append(Paragraph(
                    f"Recommendation: {_esc_xml(action)}",
                    styles["FindingAction"],
                ))
            if note_texts:
                finding_els.append(Paragraph("<b>Attorney Notes:</b>", styles["FindingBody"]))
                for note_text in note_texts:
                    finding_els.append(Paragraph(
                        f"&bull; {_esc_xml(note_text)}",
                        styles["ClauseText"],
                    ))

            # Fragility/rules omitted from client-facing PDF

            finding_els.append(Spacer(1, 6))

            # Add all finding elements — no KeepTogether to avoid large blank gaps
            elements.extend(finding_els)

    # ════════════════════════════════════════════════
    # LAST PAGE: Run Details
    # ════════════════════════════════════════════════

    elements.append(HRFlowable(width="100%", thickness=0.5, color=HexColor("#e2e8f0"),
                                spaceBefore=16, spaceAfter=8))
    elements.append(Paragraph("RUN DETAILS", styles["SynopsisHeading"]))
    elements.append(Spacer(1, 4))

    elements.append(Paragraph("Models Used:", styles["SmallMuted"]))

    extraction_model = models_used.get("extraction") or models_used.get("extractor", "")
    if extraction_model:
        elements.append(Paragraph(f"  Extraction: {_esc_xml(_model_name(extraction_model))}", styles["SmallMuted"]))
    if models_used.get("evaluator_a"):
        elements.append(Paragraph(f"  Evaluator A: {_esc_xml(_model_name(models_used['evaluator_a']))}", styles["SmallMuted"]))
    if models_used.get("evaluator_b"):
        elements.append(Paragraph(f"  Evaluator B: {_esc_xml(_model_name(models_used['evaluator_b']))}", styles["SmallMuted"]))
    if models_used.get("evaluator_c"):
        elements.append(Paragraph(f"  Evaluator C: {_esc_xml(_model_name(models_used['evaluator_c']))}", styles["SmallMuted"]))
    challenger_model = models_used.get("challenger", "")
    if challenger_model:
        elements.append(Paragraph(f"  Challenger: {_esc_xml(_model_name(challenger_model))}", styles["SmallMuted"]))
    severity_model = models_used.get("severity") or models_used.get("severity_assessor", "")
    if severity_model:
        elements.append(Paragraph(f"  Severity: {_esc_xml(_model_name(severity_model))}", styles["SmallMuted"]))

    elements.append(Spacer(1, 6))
    minutes = round(total_elapsed / 60, 1)
    elements.append(Paragraph(f"Processing: {total_api_calls} API calls total, {minutes} minutes", styles["SmallMuted"]))
    elements.append(Paragraph("Pipeline: CAM v2.5.3 -- Constrained Assertion Method", styles["SmallMuted"]))

    template_name = first_result.get("template_file", "Unknown")
    elements.append(Paragraph(f"Template file: {_esc_xml(template_name)}", styles["SmallMuted"]))

    elements.append(Spacer(1, 16))
    elements.append(Paragraph(
        "This report was generated by CAM (Constrained Assertion Method). "
        "Patent Pending. This is a diagnostic tool and does not constitute legal advice.",
        styles["Disclaimer"],
    ))

    doc.build(elements)
    logger.info(f"Combined synopsis PDF saved: {output_path}")
    return output_path
